    numberLookup: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @enum {string} */
                    type: "pan" | "aadhaar" | "gst" | "upi";
                    number: string;
                } | {
                    /** @enum {string} */
                    type: "bank_account";
                    /** @description Bank account number */
                    number: string;
                    ifsc: string;
                };
            };
        };
        responses: {
            /** @description Who holds the number (may be nobody) */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "message": "Number found",
                     *       "data": {
                     *         "found": true,
                     *         "holders": [
                     *           {
                     *             "partnerId": "01a1c439-7853-7511-a925-ea0000000000",
                     *             "name": "Ravi Kumar",
                     *             "phone": "919812345678",
                     *             "partnerType": "carpenter",
                     *             "businessName": null,
                     *             "zone": {
                     *               "id": "01a1c439-5e77-7353-bfa9-d21e3f7cf544",
                     *               "name": "TEST Pune"
                     *             },
                     *             "accountStatus": "active",
                     *             "kycState": "not_submitted",
                     *             "onboardingStep": "kyc_documents",
                     *             "startedAt": "2026-11-10T06:30:00.000Z",
                     *             "submittedAt": null,
                     *             "startedBy": {
                     *               "id": "01a1c439-6f2a-7790-85fd-9ddc90843e98",
                     *               "name": "TEST Pune ASM 1",
                     *               "role": "ASM"
                     *             },
                     *             "numberStatus": "in_use",
                     *             "canRemoveDraft": true
                     *           }
                     *         ]
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["SuccessEnvelope"] & {
                        data?: {
                            found: boolean;
                            holders: components["schemas"]["NumberHolder"][];
                        };
                    };
                };
            };
            400: components["responses"]["ValidationError"];
            401: components["responses"]["NotLoggedIn"];
            403: components["responses"]["Forbidden"];
        };
    };
